import fitz

for i in range(1, 4):
    doc = fitz.open(f"/root/paper{i}.pdf")
    print(f"=== paper{i}.pdf - Searching for identifying info ===")
    for page_num in range(doc.page_count):
        page = doc[page_num]
        text = page.get_text()
        # Search for arxiv, doi, identifiers
        lower = text.lower()
        for keyword in ['arxiv', 'doi', 'preprint', 'accepted', 'published', 'proceedings', 'conference', 'journal', 'workshop', 'icml', 'neurips', 'iclr', 'aaai', 'acl', 'emnlp', 'interspeech', 'icassp']:
            if keyword in lower:
                # Find the line containing it
                for line in text.split('\n'):
                    if keyword in line.lower():
                        print(f"  Page {page_num+1}: [{keyword}] {line.strip()[:200]}")
    doc.close()
    print()
